function dump(n, depth) {
  if (depth === undefined) depth = 0;
  var info = {
    id: n.id, name: n.name, type: n.type,
    x: Math.round(n.x), y: Math.round(n.y), w: Math.round(n.width), h: Math.round(n.height)
  };
  if (n.type === 'TEXT') {
    info.characters = n.characters;
    info.fontSize = n.fontSize;
    try { info.fontName = n.fontName; } catch(e){}
    try { info.fills = n.fills; } catch(e){}
  }
  if ('fills' in n && n.type !== 'TEXT') { try { info.fills = JSON.parse(JSON.stringify(n.fills)); } catch(e){} }
  if ('cornerRadius' in n) { try { info.cornerRadius = n.cornerRadius; } catch(e){} }
  if ('children' in n && depth < 3) {
    info.children = n.children.map(function(c){ return dump(c, depth+1); });
  }
  return info;
}
var out = {};
['3:25','3:28','3:32','3:42'].forEach(function(id){
  var n = figma.getNodeById(id);
  out[id] = n ? dump(n) : 'NOT FOUND';
});
return JSON.stringify(out, null, 1);

