function stepRow(name, iconId, title, sub, state, x, y){
  var c = mkComp(name,335, sub?56:44, WHITE,0,x,y); c.fills=[];
  var badge = figma.createFrame(); badge.resize(32,32); badge.cornerRadius=16; badge.x=0; badge.y=0; c.appendChild(badge);
  if(state==='done'){ badge.fills=solid(TINT); }
  else if(state==='current'){ badge.fills=solid(PRIMARY); }
  else { badge.fills=solid(WHITE); badge.strokes=solid(GRAY); badge.strokeWeight=1.5; }
  if(iconId){ var ic = figma.getNodeById(iconId).createInstance(); ic.resize(20,20); ic.x=6; ic.y=6; badge.appendChild(ic); }
  if(state==='done'){ var chk = figma.getNodeById('12:110').createInstance(); chk.resize(16,16); chk.x=8; chk.y=8; badge.appendChild(chk); }
  if(state==='current'){ var dot=figma.createEllipse(); dot.resize(10,10); dot.x=11; dot.y=11; dot.fills=solid(WHITE); badge.appendChild(dot); }
  var t = put(c, T(title,14,'SemiBold', state==='pending'?GRAY:INK), 44, 3);
  if(sub){ put(c, T(sub,12,'Regular',MUTED), 44, 26); }
  return c;
}
