function makeCentered(id, w, h, hug){
  var c=figma.getNodeById(id);
  c.layoutMode='HORIZONTAL';
  c.counterAxisAlignItems='CENTER';
  c.primaryAxisAlignItems='CENTER';
  if(hug){ c.primaryAxisSizingMode='AUTO'; c.paddingLeft=18; c.paddingRight=18; }
  else { c.primaryAxisSizingMode='FIXED'; }
  c.counterAxisSizingMode='FIXED';
  if(!hug && w) c.resize(w,h);
  else if(hug) c.resize(c.width,h);
  return c.name+' ok';
}
